function localNow(){const d=new Date();const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`}
function localToday(){return localNow().slice(0,10)}
function localMoney(v){return Math.round((Number(v)+Number.EPSILON)*100)/100}
function localNext(db,key){const id=Number(db.seq[key]||1);db.seq[key]=id+1;return id}
function localSafeUser(u){if(!u)return null;const {passwordHash,...safe}=u;return {...safe}}
function localFindUser(db,id){return db.users.find(u=>Number(u.id)===Number(id)&&u.activo!==0)||null}
